'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),vm=require('node:vm');
const F=require('./native-fixtures-20261003.cjs'),e=F.environment(),c=e.ctx,x=F.examples(c),B=c.JYBaziFunctional,S=c.JYVedicSudarsanaBPHS,plain=x=>JSON.parse(JSON.stringify(x)),results=[];
function test(name,fn){fn();results.push({name,status:'passed'});console.log('PASS '+name);}
function chart(stems,month,branches){const ps=Object.fromEntries(['year','month','day','hour'].map((k,i)=>[k,{gan:stems[i],zhi:branches?.[i]|| (i===1?month:'子')}])),z={pillars:ps,dm:stems[2]};z.classicalAssessment=c.JYBaziClassical.compute(z);z.functionalAssessment=B.compute(z);return z;}
const roots=(s,branches)=>B.rootPremise(s,Object.fromEntries(['year','month','day','hour'].map((k,i)=>[k,{zhi:branches[i]}])));
test('actual four-branch roots use every hidden stem, with exact and element roots distinct',()=>{const a=roots('甲','辰未亥卯');assert.equal(a.roots.length,4);assert.equal(a.roots.filter(p=>p.exactStem).length,1);assert.equal(a.heavyRoots,2);assert.equal(a.lightRoots,2);});
test('grave roots retain literal storage without requiring a clash to open them',()=>{assert(roots('丙','戌丑酉子').hasRoot);assert.equal(roots('丁','丑丑酉子').hasRoot,false);assert.equal(roots('乙','戌丑酉子').hasRoot,false);});
test('a clash is actual evidence and does not erase a root',()=>{const a=roots('甲','寅申子子');assert.equal(a.roots[0].clashedBy[0],'month');assert(a.hasRoot);});
test('yin longevity analogies never fabricate hidden wood in Wu or fire in You',()=>{assert.equal(roots('乙','午午午午').hasRoot,false);assert.equal(roots('丁','酉酉酉酉').hasRoot,false);assert(x.b.functionalAssessment.yinChangshengAnalogies.every(p=>p.literalHiddenRoot===false));});
test('invalid stems and malformed pillars do not certify complete calculations',()=>{assert.throws(()=>B.rootPremise('甲乙',x.b.pillars));assert.equal(B.compute({pillars:{}}).status,'insufficient-data');const z=plain(x.b);z.pillars.year.gan='甲乙';assert.equal(B.compute(z).status,'insufficient-data');});
test('unknown birth time excludes all full-chart functional judgments',()=>{const z=plain(x.b);z.birthTimeUnknown=true;assert.equal(B.compute(z).status,'insufficient-data');assert.equal(B.compute(z).rootContext.length,0);});
test('intervening controller blocks an actual five-stem pair',()=>{const z=chart('癸甲丙戊','寅');const p=z.functionalAssessment.combinations.find(p=>p.stems==='癸戊');assert.equal(p.status,'blocked-by-controller');assert.deepEqual(plain(p.controllers.map(p=>p.stem)),['甲']);});
test('a distant year-hour pair is retained as partial without a manufactured percentage',()=>{const p=chart('甲丙壬己','寅').functionalAssessment.combinations.find(p=>p.stems==='甲己');assert.equal(p.status,'distant-partial');assert.equal(p.removalCertified,false);assert(!Object.hasOwn(p,'probability'));});
test('day-self combinations do not remove the day masters own spouse or officer',()=>{const p=chart('壬庚乙戊','酉').functionalAssessment.combinations.find(p=>p.stems==='庚乙');assert(p.daySelfDoesNotRemove);assert.equal(p.transformationCertified,false);});
test('an adjacent rival can preempt a more distant day-self pair',()=>{const p=chart('庚乙乙壬','酉').functionalAssessment.combinations.find(p=>p.a==='year'&&p.b==='day');assert.equal(p.status,'nearer-rival-preempts');assert(p.preempted);});
test('contested adjacent pairs are distinguished from separated partners',()=>{const p=chart('辛丙辛壬','午').functionalAssessment.combinations.find(p=>p.stems==='辛丙');assert(p.competition);const a=chart('庚乙甲乙','酉',['午','酉','子','亥']).functionalAssessment;assert(a.combinations.every(p=>!p.competition));});
test('six printed pure-mixed examples reproduce their role mechanisms',()=>{for(const [stems,m,cls]of [['甲丙辛壬','寅','pure'],['庚壬戊甲','申','pure'],['乙己癸壬','未','pure'],['乙己壬甲','未','mixed'],['戊壬甲丙','辰','mixed'],['丁己癸壬','午','mixed']]){const a=chart(stems,m).functionalAssessment.pureMixed.find(p=>p.match);assert(a);assert.equal(a.classification,cls);assert.equal(a.fullPatternCertified,false);}});
test('Jia-Chen Ren is retained as a printed exception and never inserted into hidden stems',()=>{const a=chart('戊壬甲丙','辰').functionalAssessment.pureMixed.find(p=>p.match);assert.equal(a.exactHiddenStem,false);assert.equal(a.monthlyOrigin,'printed-source-exception');assert(!roots('壬','辰辰辰辰').hasExactRoot);});
test('the four source ordered-rescue cases use actual year-month-hour positions',()=>{for(const [stems,m]of [['丁戊甲壬','酉'],['己甲甲癸','子'],['庚甲壬丙','寅'],['癸己己辛','卯']]){const a=chart(stems,m).functionalAssessment.orderedMechanisms.find(p=>p.applicable);assert(a);assert(a.pairs.some(p=>p.sequence==='source-rescue-order'));assert.equal(a.fullPatternCertified,false);}});
test('reverse cases with an adverse hour are distinctly recorded',()=>{for(const [stems,m]of [['戊壬甲丁','酉'],['癸甲甲己','子'],['丙甲壬庚','寅'],['辛己己癸','卯']]){const a=chart(stems,m).functionalAssessment.orderedMechanisms.find(p=>p.applicable);assert(a.pairs.some(p=>p.sequence==='source-late-disruption'));}});
test('nine position fixtures distinguish seven printed layouts and two reconstructions',()=>{const layouts=x.b.functionalAssessment.positionLayouts;assert.equal(layouts.length,9);assert.equal(layouts.filter(p=>p.provenance==='explicit-source-layout').length,7);for(const r of layouts){const z=chart(r.stems,r.month).functionalAssessment.positionLayouts.find(p=>p.id===r.id);assert(z.match);assert.equal(z.fullCalendarVerified,false);}});
test('BPHS literal-loss and opposite-polarity variants compute separate natures',()=>{const p={complete:true,good:2,bad:4,neutral:1};assert.equal(S.adjustNature('benefic',p).nature,'neutral');assert.equal(S.adjustNature('benefic',p,'polarity-reversal').nature,'malefic');assert.equal(S.adjustNature('benefic',{complete:false}).nature,'undetermined');});
test('equal-count raw-bala party sums and strongest-member variants may disagree',()=>{const a=[{planet:'a',nature:'benefic',strength:70},{planet:'b',nature:'benefic',strength:60},{planet:'c',nature:'malefic',strength:100},{planet:'d',nature:'malefic',strength:20}];assert.equal(S.resolveInfluence(a).assessment,'favorable');assert.equal(S.resolveInfluence(a,'strongest-member').assessment,'adverse');assert.throws(()=>S.resolveInfluence(a,'relative-percent'));});
test('equal strength is mixed while missing node raw-bala remains undetermined',()=>{assert.equal(S.resolveInfluence([{planet:'a',nature:'benefic',strength:60},{planet:'b',nature:'malefic',strength:60}]).assessment,'mixed');assert.equal(S.resolveInfluence([{planet:'a',nature:'benefic',strength:60},{planet:'Rahu',nature:'malefic',strength:null}]).assessment,'undetermined');});
test('four actual entry instants have 196 phala rows and 28 independently computed BPHS strength rows',()=>{const b=x.v.sudarsana.bphs;assert.equal(b.status,'calculated');assert.equal(Object.keys(b.entries).length,4);assert.equal(Object.values(b.entries).reduce((n,e)=>n+e.context.phala.rows.length,0),196);assert.equal(Object.values(b.entries).reduce((n,e)=>n+e.context.strength.planets.length,0),28);assert(Object.values(b.entries).every(e=>e.context.strength.school==='bphs'&&e.context.strength.complete));assert(new Set(Object.values(b.entries).map(e=>e.context.utc)).size>=3);});
test('all nine category points and complementary half-phala arithmetic are exact',()=>{assert.deepEqual(plain(S.points),{exalted:60,moolatrikona:45,own:30,'great-friend':22,friend:15,neutral:8,enemy:4,'great-enemy':2,debilitated:0});for(const e of Object.values(x.v.sudarsana.bphs.entries))for(const r of e.context.phala.rows){assert.equal(r.subha,S.points[r.category]*r.factor);assert.equal(r.subha+r.asubha,r.division===1?60:30);assert.equal(r.factor,r.division===1?1:.5);}});
test('Mercury joined to any malefic uses BPHS literal nature with commentary separate',()=>{const z=plain(x.v);z.planets.Mercury.sign=z.planets.Sun.sign;z.planets.Moon.longitude=c.JYVedic.norm(z.planets.Sun.longitude+250);const n=S.natural(z);assert.equal(n.main.Mercury,'malefic');assert(n.mercuryMaleficCompanions.includes('Sun'));assert(n.commentaryVariant);});
test('occupants take priority over aspectors and lord fallback',()=>{for(const e of Object.values(x.v.sudarsana.bphs.entries))for(const w of Object.values(e.readings))for(const h of w.houses){assert.equal(h.mode,h.occupants.length?'occupants':h.aspectors.length?'aspects':'lord');assert.equal(h.sign,(w.referenceSign+h.house-1)%12);}});
test('source Sun-first-house, exalted-malefic and sole-node exceptions are computed',()=>{const z=plain(x.v),ct=S.entryContext(z),sunSign=ct.positions.Sun.sign,w=S.wheel(z,ct,sunSign,'Sun');assert(w.houses[0].factors.find(p=>p.planet==='Sun').sunException);ct.positions.Rahu.sign=0;for(const k of c.JYVedic.KEYS)if(k!=='Rahu'&&ct.positions[k].sign===0)ct.positions[k].sign=1;const node=S.wheel(z,ct,0).houses[0].periodPlacements.find(p=>p.planet==='Rahu');assert(node.soleNode);assert.equal(node.assessment,'adverse');assert.equal(node.natalBav,null);ct.positions.Mars={sign:9,longitude:298,degree:28};ct.states.Mars.literal.nature='malefic';const exalt=S.wheel(z,ct,9).houses[0].factors.find(p=>p.planet==='Mars');assert(exalt.exaltedException);assert.equal(exalt.nature,'neutral');assert.equal(S.wheel(z,{status:'insufficient-data'},null).status,'insufficient-data');});
test('own house lord support is local and the natural-only alternative is preserved',()=>{let found=0;for(const e of Object.values(x.v.sudarsana.bphs.entries))for(const w of Object.values(e.readings))for(const h of w.houses){if(h.lordNatureOverride){assert(h.factors.find(p=>p.planet===h.lord).ownLordException);found++;}assert(h.variants.naturalOnly);}assert(found>0);});
