test('Bazi compatibility keeps separate A and B functional facts and hides unknown-hour judgments',()=>{assert.equal(x.comp.personA.functionalAssessment.status,'calculated-structural');assert.equal(x.comp.personB.functionalAssessment.status,'calculated-structural');const z=plain(x.b);z.birthTimeUnknown=true;const a=c.BaziSuiteCore.createCompatibility(z,x.bb,{scenarioId:'couple'});assert.equal(a.personA.unknownTime,true);assert.equal(a.personA.pillars.length,3);assert(!a.personA.functionalAssessment);});
