test('lossless dense rows and JSON references expand to unchanged actual data',()=>{const rows=[{a:1,b:{z:2}},{a:2,b:{z:2}},{a:3,b:{z:2}}],dense=c.JYNativeAnalysis.denseRows(rows);function restore(v){if(v==null||typeof v!=='object')return v;if(Array.isArray(v))return v.map(restore);if(v.$table)return v.rows.map(row=>Object.fromEntries(v.$table.map((k,i)=>[k,restore(row[i])])));return Object.fromEntries(Object.entries(v).map(([k,z])=>[k,restore(z)]));}assert.deepEqual(restore(plain(dense)),rows);assert.deepEqual(plain(c.JYNativeAnalysis.compact([x.b.functionalAssessment,x.b.functionalAssessment]))[1],{$ref:'#/0'});});
test('all 120 Qiongtong source entries retain context and any literal root predicates use actual branches',()=>{for(const dm of '甲乙丙丁戊己庚辛壬癸')for(const month of '寅卯辰巳午未申酉戌亥子丑'){const z=chart('庚丙'+dm+'壬',month),facts={dm,stems:['year','month','day','hour'].map(k=>({pillar:k,stem:z.pillars[k].gan})),hidden:['year','month','day','hour'].flatMap(k=>Array.from({子:'癸',丑:'己癸辛',寅:'甲丙戊',卯:'乙',辰:'戊乙癸',巳:'丙戊庚',午:'丁己',未:'己丁乙',申:'庚壬戊',酉:'辛',戌:'戊辛丁',亥:'壬甲'}[z.pillars[k].zhi]).map(stem=>({pillar:k,branch:z.pillars[k].zhi,stem})))};const a=c.JYBaziQiongtong.evaluate(facts);assert.equal(a.rootContext.length,10);assert(a.sourceParagraphs.length);for(const q of a.checks)for(const p of q.conditions)if(p.id.startsWith('root-')){const r=p.evidence.rootPremise;assert.equal(p.satisfied,p.id.endsWith('無根')?!r.hasRoot:r.hasRoot);}}});
